const clock = new THREE.Clock();

scene.background = new THREE.Color(0xf4f7fb);

renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;

const ambientLight = new THREE.AmbientLight(0x7f8aa6, 0.35);
const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
keyLight.position.set(6, 8, 6);
keyLight.castShadow = true;

const pointLight = new THREE.PointLight(0x00d2ff, 1.8, 25);
pointLight.position.set(-4, 5, -4);
pointLight.castShadow = true;

scene.add(ambientLight, keyLight, pointLight);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(8, 64),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.92, metalness: 0.02 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -2;
floor.receiveShadow = true;
scene.add(floor);

const cubeGeometry = new THREE.BoxGeometry(2.2, 2.2, 2.2);
const cubeMaterial = new THREE.MeshStandardMaterial({
  color: 0xe74c3c,
  roughness: 0.3,
  metalness: 0.1
});
const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
cube.castShadow = true;
cube.receiveShadow = true;
cube.position.y = 0.2;
scene.add(cube);

camera.position.set(5, 3, 6);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  cube.rotation.x = t * 0.6;
  cube.rotation.y = t * 0.4;

  pointLight.position.y = 5 + Math.sin(t * 0.8) * 0.8;

  controls.update();
  renderer.render(scene, camera);
}

animate();

